/* a size for each idea on the ideas wall: small, wide, tall or big */
const SIZES = 'wsbtwswtbswtswbwtswsbtwstwbswtwsbwtsw';
const kclass = (h) => h.replace(/class="([^"]*)"/g, (m, c) => 'class="' + c.split(' ').filter(Boolean).map((x) => 'k-' + x).join(' ') + '"');
export const IDEAS = W.map(([g, where, page, ar, d, html], i) => ({ n: i + 1, g, where, page, ar, d, size: SIZES[i % SIZES.length], html: kclass(html) }));
